class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        temp = [(0, 0)]
        i = 0

        while i < len(prices):
            pos = 2 * i + 2
            new = temp[0][1] + prices[i]

            if i == temp[0][0]:
                temp.pop(0)
            else:
                while temp and temp[-1][1] >= new:
                    temp.pop()
                temp.append((pos, new))

            i += 1

        return temp[0][1]
